        try:
            metadata = _get_collection_metadata(collection_name)
        except ValueError as exc:
            raise AnsibleError(to_native(exc))
        routes = metadata.get('plugin_routing', {}).get('module_utils', {})
        relative = candidate[self.root_length:]
        for length in range(len(relative), 0, -1):
            entry = routes.get('.'.join(relative[:length]))
            if entry and (entry.get('redirect') or entry.get('tombstone')):
